Path *Pathfinder::findSafePath(const Object *obj, const LocomotorSet &locomotorSet,
	const Coord3D *from, const Coord3D *repulsorPos1, const Coord3D *repulsorPos2,
	Real repulsorRadius)
{
	if (!*reinterpret_cast<Bool *>(reinterpret_cast<char *>(this) + 8))
		return false;
	const Int MAX_CELLS = 2000;
	Bool centerInCell;
	Int radius;
	getRadiusAndCenter(obj, radius, centerInCell);
	Real repulsorDistSqr = repulsorRadius * repulsorRadius;
	Int cellCount = 0;
	Bool isHuman = true;
	if (obj && obj->getControllingPlayer() &&
		(obj->getControllingPlayer()->getPlayerType() == PLAYER_COMPUTER))
		isHuman = false;

	Rva003EC8C0PathVector *pathCells =
		reinterpret_cast<Rva003EC8C0PathVector *>(reinterpret_cast<char *>(this) + 0x2470c);
	_STL::random_access_iterator_tag pathCopyTag;
	pathCells->m_end = _STL::__copy(pathCells->m_end, pathCells->m_end,
		pathCells->m_begin, pathCopyTag, &cellCount);
	BfmeGridAL *zoneManager = reinterpret_cast<BfmeGridAL *>(reinterpret_cast<char *>(this) + 0xc9c);
	zoneManager->bfmeFillAL();

	ICoord2D startCellNdx;
	worldToCell(obj->getPosition(), &startCellNdx);
	ICoord2D parentCellNdx;
	worldToCell(obj->getPosition(), &parentCellNdx);
	PathfindCell *parentCell = getCell((PathfindLayerEnum)obj->getLayer(), parentCellNdx.x, parentCellNdx.y);
	if (parentCell == NULL)
		return false;
	if (*reinterpret_cast<void **>(const_cast<char *>(reinterpret_cast<const char *>(obj)) + 0x204) == NULL)
		return false;
	Rva003EC8C0CellView *parentView = reinterpret_cast<Rva003EC8C0CellView *>(parentCell);
	if (parentView->m_info == NULL)
	{
		PathfindCellInfo **freeList = reinterpret_cast<PathfindCellInfo **>(0x012F1094);
		if (*freeList == NULL)
			PathfindCellInfo::allocateCellInfos();
		parentView->m_info = bfmeAcquirePathfindCellInfo(freeList, parentCell, &parentCellNdx);
	}
	else
	{
		reinterpret_cast<Rva003EC8C0InfoView *>(parentView->m_info)->m_prevOpen = NULL;
	}
	parentCell->startPathfind(NULL);
	reinterpret_cast<Gen_003D6400 *>(this)->bfmeCopyIndexed(reinterpret_cast<BfmeThingBRE *>(parentCell));

	Real farthestDistanceSqr = 0;
	while ((parentCell = reinterpret_cast<PathfindCell *>(reinterpret_cast<Gen_003D6490 *>(this)->bfmeTakeFirstLive())) != NULL)
	{
		Coord3D cellCenter;
		Rva003EC8C0CellView *cellView = reinterpret_cast<Rva003EC8C0CellView *>(parentCell);
		Rva003EC8C0InfoView *info = reinterpret_cast<Rva003EC8C0InfoView *>(cellView->m_info);
		adjustCoordToCell(info->m_pos.x, info->m_pos.y, centerInCell, cellCenter,
			(PathfindLayerEnum)((cellView->m_packed >> 6) & 0x3f));
		Real dx = cellCenter.x - repulsorPos1->x;
		Real dy = cellCenter.y - repulsorPos1->y;
		Bool ok = false;
		Real distSqr = dx * dx + dy * dy;
		dx = cellCenter.x - repulsorPos2->x;
		dy = cellCenter.y - repulsorPos2->y;
		Real distSqr2 = dx * dx + dy * dy;
		if (distSqr2 < distSqr)
			distSqr = distSqr2;
		if (distSqr > repulsorDistSqr)
			ok = true;
		if (reinterpret_cast<Gen_003D6440 *>(this)->bfmeFirstLive() == 0 && cellCount > 0)
			ok = true;
		if (distSqr > farthestDistanceSqr)
		{
			farthestDistanceSqr = distSqr;
			if (cellCount > MAX_CELLS)
				ok = true;
		}
		if (ok && checkDestination(obj, info->m_pos.x, info->m_pos.y,
			(PathfindLayerEnum)((cellView->m_packed >> 6) & 0x3f), radius, centerInCell))
		{
			Path *path = buildActualPath(obj, locomotorSet.getValidSurfaces(), obj->getPosition(),
				parentCell, centerInCell, false);
			reinterpret_cast<BfmeThingNO *>(parentCell)->bfmeMoveNO(
				reinterpret_cast<BfmeNodeNO **>(reinterpret_cast<char *>(this) + 0x838));
			*reinterpret_cast<Bool *>(reinterpret_cast<char *>(this) + 0x83c) = false;
			reset();
			return path;
		}
		reinterpret_cast<BfmeThingNO *>(parentCell)->bfmeMoveNO(
			reinterpret_cast<BfmeNodeNO **>(reinterpret_cast<char *>(this) + 0x838));
		Rva003DAE40Helper *layerHelper = reinterpret_cast<Rva003DAE40Helper *>(this);
		layerHelper->checkChangeLayers(parentCell, obj);
		Rva003E6EE0Helper *neighborHelper = reinterpret_cast<Rva003E6EE0Helper *>(this);
		cellCount += neighborHelper->examineNeighboringCells(parentCell, NULL, locomotorSet,
			isHuman, centerInCell, radius, startCellNdx, obj, NO_ATTACK);
	}
	*reinterpret_cast<Bool *>(reinterpret_cast<char *>(this) + 0x83c) = false;
	reset();
	return false;
}
